#!/usr/bin/env node
/**
 * apps/mobile/scripts/build-splash-dark.mjs — the dark-ground splash icon.
 *
 * WHY THIS EXISTS: the canonical splash mark (assets/images/splash-icon.png,
 * generated by ../../scripts/brand/build-app-icons.mjs) draws the U-vessel
 * in ink #262019 on transparency. The dark splash variant in app.config.ts
 * swaps ONLY the ground to the dark paper #262019 — the vessel stroke is
 * then 1:1 against its own ground and the dark-mode cold boot shows a
 * near-empty screen with only the sienna cornerstone visible.
 *
 * The fix is a DARK-GROUND derivation of the SAME canonical mark: identical
 * geometry (parsed from src/brand/mark.ts — never restated), paper ink
 * #F5F1E8 stroke, same sienna cornerstone, same hairline weight and box
 * fraction as the light asset (STROKE_COMPONENT · box 0.8 · 1024 canvas).
 * It is NOT a competing design and it does NOT touch any existing generated
 * file — splash-icon.png and every other brand asset stay byte-identical,
 * owned by the root script's --check gate.
 *
 * Integration note for the lead: this derivation belongs in the canonical
 * asset table (scripts/brand/build-app-icons.mjs — "splash-icon-dark.png"),
 * alongside its light twin. Until the root script adopts it, this
 * mobile-local generator keeps the exact same contract: parse mark.ts,
 * fail loudly if its shape changes, and byte-verify in --check mode
 * (wired into `npm run tokens:check` from apps/mobile/package.json).
 *
 * Modes:
 *   (bare)   write assets/images/splash-icon-dark.png (requires sharp)
 *   --check  byte-compare the regenerated PNG vs the committed file
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { createRequire } from "node:module";

const MOBILE = join(dirname(fileURLToPath(import.meta.url)), "..");
const MARK_TS = join(MOBILE, "src", "brand", "mark.ts");
const OUT = join(MOBILE, "assets", "images", "splash-icon-dark.png");

/* ── the canonical geometry — parsed from mark.ts (never restated) ── */

const src = readFileSync(MARK_TS, "utf8");

function need(re, name, cast = (x) => x) {
  const m = re.exec(src);
  if (!m) {
    console.error(`build-splash-dark: cannot find ${name} in mark.ts — the brand source changed shape; update the parser.`);
    process.exit(1);
  }
  return cast(m.slice(1));
}

const VESSEL = need(/MARK_VESSEL_PATH = '([^']+)'/, "MARK_VESSEL_PATH", (g) => g[0]);
const KEY = need(/MARK_CORNERSTONE = \{ x: (\d+), y: (\d+), size: (\d+) \}/, "MARK_CORNERSTONE", (g) => g.map(Number));

/* Same numbers as the root script's light splash asset (its asset table:
 * "splash-icon.png": markSvg({ stroke: STROKE_COMPONENT, box: 0.8 })). */
const STROKE_COMPONENT = 1.5; // mark.ts: hairline at the 32-grid design size
const BOX = 0.8; // the mark occupies 80% of the canvas, centred
const CANVAS = 1024;
const PAPER_INK = "#F5F1E8"; // ds.light.bg / ds.dark.text — the paper rung
const SIENNA = "#C43E16"; // the cornerstone — unchanged on both grounds

const vb = 32 / BOX;
const off = +((vb - 32) / 2).toFixed(4);
const svg =
  `<svg xmlns="http://www.w3.org/2000/svg" width="${CANVAS}" height="${CANVAS}" viewBox="${-off} ${-off} ${vb} ${vb}">` +
  `<g fill="none" stroke="${PAPER_INK}" stroke-width="${STROKE_COMPONENT}" stroke-linecap="round" stroke-linejoin="round">` +
  `<path d="${VESSEL}"/></g>` +
  `<rect x="${KEY[0]}" y="${KEY[1]}" width="${KEY[2]}" height="${KEY[2]}" fill="${SIENNA}"/></svg>`;

/* sharp resolves from apps/mobile's devDependencies (same rule as the root script). */
const require_ = createRequire(join(MOBILE, "package.json"));
const sharpMod = require_("sharp");

const png = await sharpMod(Buffer.from(svg)).png({ compressionLevel: 9 }).toBuffer();

if (process.argv.includes("--check")) {
  let committed = null;
  try {
    committed = readFileSync(OUT);
  } catch {
    console.error("build-splash-dark: ✖ splash-icon-dark.png MISSING — run: npm run splash:dark (apps/mobile) and commit.");
    process.exit(1);
  }
  if (Buffer.compare(png, committed) === 0) {
    console.log("build-splash-dark: splash-icon-dark.png byte-identical to the one mark. ✔");
  } else {
    console.error("build-splash-dark: ✖ DRIFT — regenerate with `npm run splash:dark` (apps/mobile) and commit.");
    process.exit(1);
  }
} else {
  writeFileSync(OUT, png);
  console.log(`build-splash-dark: written ${OUT} (${png.length} bytes) — paper-ink vessel on transparent, sienna cornerstone.`);
}
